static void calibirq(void) {
	HAL_DisableDSHOTTIMERDMATrigger();
	DL_Timer_disableEvent(IOTIM_INST, DL_TIMERG_EVENT_ROUTE_1, IOTIM_DMA_EVENT);

	/* CC0 is already in rising-edge capture mode from initio().
		Enable CC0 capture interrupt (fires on every configured edge). */
    DL_Timer_stopCounter(IOTIM_INST);

    HAL_setTIMERPrescaler(IOTIM_INST, CLK_MHZ - 1); // 1us resolution
	DL_Timer_clearInterruptStatus(IOTIM_INST , IOTIM_INTERRUPT_EVENT);
	DL_Timer_enableInterrupt(IOTIM_INST , IOTIM_INTERRUPT_EVENT);
	
	/* change to use ZCOND to detect end of packet */
    DL_Timer_setCaptureCompareCtl(IOTIM_INST,
    DL_TIMER_CC_MODE_CAPTURE, (DL_TIMER_CC_ZCOND_TRIG_RISE | DL_TIMER_CC_ACOND_TIMCLK | DL_TIMER_CC_CCOND_TRIG_FALL),
    IOTIM_INDEX);

	ioirq = servoirq;
    DL_Timer_startCounter(IOTIM_INST);
}

