static void dshotdma(void) {

	static const char gcr[] = {0x19, 0x1b, 0x12, 0x13, 0x1d, 0x15, 0x16, 0x17, 0x1a, 0x09, 0x0a, 0x0b, 0x1e, 0x0d, 0x0e, 0x0f};
	static int cmd, cnt, rep;

	/* if memory to peripheral ,ie in TX mode */
	if (HAL_isDSHOTTIMERDMAinTX()) { /* prepare the dshotbuf2 frame to send for case of Bidirectional DShot*/
		/* once a TX is done we switch back the timer to capture mode */
		dshotreset();
		if (!dshotval) {
			int a = ertm ? min(ertm, 65408) : 65408;
			int b = 0;
			while (a > 511) a >>= 1, ++b; //Convert RPM to 12 bit format, this is the normalization step
			dshotval = a | (b << 9); //dshotval = mantissa | (exponent << 9)
		}
		int a = dshotval << 4 | dshotcrc(dshotval, 1); //Append CRC 4 bits, note CRC is inverted
		int b = 0;

		/* GCR Encoding (16-bit -> 20-bit) , b is the 20-bit GCR-encoded value after this loop */
		for (int i = 0, j = 0; i < 16; i += 4, j += 5) b |= gcr[a >> i & 0xf] << j;

		/* NRZL Bit Encoding */
		for (int p = -1, i = 19; i >= 0; --i) {
			if (b >> i & 1) p = ~p;
			dshotbuf2[20 - i] = p;
		}
		if (!rep || !--rep) dshotval = 0;
		return;
	}

	if (dshotinv) { // Bidirectional DSHOT
		/* Disable DMA channel */
		HAL_DisableDSHOTTIMERDMATrigger();
		 
		/* Clear events and interrupt status */
		DL_Timer_clearInterruptStatus(IOTIM_INST, DL_TIMERG_INTERRUPT_LOAD_EVENT|IOTIM_INTERRUPT_EVENT);
		DL_Timer_clearEventsStatus(IOTIM_INST, DL_TIMERG_EVENT_ROUTE_1, IOTIM_DMA_EVENT|DL_TIMER_EVENT_LOAD_EVENT);
		DL_Timer_disableEvent(IOTIM_INST, DL_TIMERG_EVENT_ROUTE_1, (IOTIM_DMA_EVENT));

		/* Set to PWM output and inverted mode */
		DL_Timer_setCaptureCompareCtl(IOTIM_INST,
		DL_TIMER_CC_MODE_COMPARE, (DL_TIMER_CC_ZCOND_NONE | DL_TIMER_CC_ACOND_TIMCLK | DL_TIMER_CC_CCOND_NOCAPTURE),
		IOTIM_INDEX);
		
		/* set action to high and make zero event occur to force the output to high state*/
        DL_Timer_setCaptureCompareAction(IOTIM_INST,
            (DL_TIMER_CC_ZACT_CCP_HIGH | DL_TIMER_CC_CUACT_CCP_HIGH),
			IOTIM_INDEX);
		DL_Timer_setTimerCount(IOTIM_INST,-1);

		//Force update the CC value to 0
	    DL_Timer_setCaptCompUpdateMethod(IOTIM_INST, DL_TIMER_CC_UPDATE_METHOD_IMMEDIATE, IOTIM_INDEX);
		DL_Timer_setCaptureCompareValue(IOTIM_INST, 0, IOTIM_INDEX);
	    DL_Timer_setCaptCompUpdateMethod(IOTIM_INST, DL_TIMER_CC_UPDATE_METHOD_ZERO_OR_LOAD_EVT, IOTIM_INDEX);

		/* Configure inverted PWM */
        DL_Timer_setCaptureCompareAction(IOTIM_INST,
            (DL_TIMER_CC_ZACT_CCP_LOW | DL_TIMER_CC_CUACT_CCP_HIGH),
			IOTIM_INDEX);
			
		/* set pin to output */
    	DL_Timer_setCCPDirection(IOTIM_INST , IOTIM_OUTPUT);

		HAL_setDSHOTTIMERDMATriggerTX((uint32_t)&dshotbuf2[0], 23);

		__disable_irq();
		DL_Timer_setLoadValue(IOTIM_INST, dshotarr2);		
		DL_Timer_setTimerCount(IOTIM_INST, dshotarr2 - CLK_CNT(IOTIM_TIMER_CLOCK, 33333));// 30us output delay
		DL_Timer_enableEvent(IOTIM_INST, DL_TIMERG_EVENT_ROUTE_1, (DL_TIMER_EVENT_LOAD_EVENT));
		__enable_irq();
	}

