			dshotresync();
			return;
		}
		x <<= 1;

		if (dshotbuf1[i + 1] -dshotbuf1[i] >= z) x |= 1; // High time > one-fourth bit time is condition to detect bit as 1
		bitTime_buff[i>>1]=dshotbuf1[i + 1] -dshotbuf1[i];
	}

	
